SELECT 
    am.ACCOUNT_NUMBER,
    am.CUSTOMER,
    cm.CUS_SHORT_NAME,
    cm.CLASSIFICATION,
    am.CATEGORY ,
    am.CATEGORY_DESC,
    am.CURRENCY,
    am.ONLINE_ACTUAL_BAL,
        CASE 
        WHEN liab.CUSTOMER IS NOT NULL THEN 'WITH LIABILITY' 
        ELSE 'NO LIABILITY'
    END AS LIABILITY_STATUS,
    case 
    	WHEN liab.CUSTOMER IS NOT NULL THEN  ex.ExposureActual
    	ELSE 0
    end LOAN_EXPOSURE_ACTUAL,
            cm.BUSINESS_SEGMENT, 
case when cm.BUSINESS_SEGMENT in ('270','250') then 'CONSUMER BANKING'
		when cm.BUSINESS_SEGMENT in ('200') then 'COMMERCIAL & BUSINESS BANKING'
		when cm.BUSINESS_SEGMENT in ('100') then 'TREASURY'
		when cm.BUSINESS_SEGMENT in ('150') then 'CORPORATE'
end as BUSINESS_UNIT,
cm.BUSINESS_SEGMENT_DESC, cm.SUB_SEGEMENT, cm.SUB_SEGEMENT_DESC, cm.CUSTOMER_BRANCH_NAME ,cm.ACCOUNT_OFFICER_NAME ,cm.CUS_ACC_OFFICER
FROM 
    dbcba.KE_Accounts_Master am
INNER JOIN 
    dbcba.KE_Customer_Master cm ON am.CUSTOMER = cm.CUSTOMER_NUMBER 
                                 AND am.EXTRACTION_DATE = cm.EXTRACTION_DATE
left join (
            SELECT CUSTOMER
            FROM dbcba.KE_Accounts_Master am
            WHERE am.EXTRACTION_DATE = (SELECT MAX(processing_date) FROM dbcba.end_of_day)
              AND am.PRODUCT_LINE = 'LENDING' 
              AND am.ARR_STATUS IN ('CURRENT', 'EXPIRED')) liab
              on am.CUSTOMER=liab.CUSTOMER
LEFT JOIN (SELECT substring(RECID,1,6) as customer_no, sum (Deal_balance) as ExposureActual
FROM
stgke.STG_ECB_TOTAL_EXPOSURE 
where LOAD_DATE=(select MAX(PROCESSING_DATE) FROM dbcba.end_of_day)
group by substring(RECID,1,6)
) ex
on am.CUSTOMER =ex.customer_no
WHERE 
    am.EXTRACTION_DATE = (SELECT MAX(PROCESSING_DATE) FROM dbcba.end_of_day)
    AND am.PRODUCT_LINE = 'ACCOUNTS'
    AND cm.BUSINESS_SEGMENT NOT IN ('100','150') 
